CREATE TABLE IF NOT EXISTS lms.categories (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  name TEXT NOT NULL UNIQUE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

ALTER TABLE lms.categories ENABLE ROW LEVEL SECURITY;

ALTER TABLE lms.module_versions
  ADD CONSTRAINT module_versions_language_check CHECK (language IN ('en', 'zh'));

UPDATE lms.module_versions
SET language = 'zh'
WHERE storage_path LIKE '%/zh/%' AND language = 'en';

CREATE UNIQUE INDEX IF NOT EXISTS idx_module_versions_module_language_version
