CREATE OR REPLACE FUNCTION lms.is_assigned_teacher(target_learner_id UUID)
RETURNS BOOLEAN
LANGUAGE sql
SECURITY DEFINER
SET search_path = lms
AS $$
  SELECT lms.is_teacher()
    AND EXISTS (
      SELECT 1
      FROM lms.teacher_assignments
      WHERE teacher_id = auth.uid()
        AND learner_id = target_learner_id
        AND is_active = TRUE
    );
$$;

CREATE OR REPLACE FUNCTION lms.is_event_manager(target_event_id UUID)
RETURNS BOOLEAN
LANGUAGE sql
SECURITY DEFINER
SET search_path = lms
AS $$
  SELECT lms.is_admin()
    OR EXISTS (
      SELECT 1
      FROM lms.events
      WHERE id = target_event_id
        AND deleted_at IS NULL
        AND (created_by = auth.uid() OR teacher_id = auth.uid())
        AND lms.is_teacher()
    );
$$;

-- Keep role-changing writes outside direct user clients.
