-- Storage buckets:
-- study-notes: modules/{module_id}/{language}/{version}/{filename}
-- avatars: optional public avatar objects scoped by auth uid folder.
DROP POLICY IF EXISTS "storage: authenticated read" ON storage.objects;
DROP POLICY IF EXISTS "storage: admin write" ON storage.objects;
CREATE POLICY "storage: study notes read accessible current version"
  ON storage.objects
  FOR SELECT
  USING (
    bucket_id = 'study-notes'
    AND lms.is_active_app_user(auth.uid())
    AND (
      lms.is_admin()
      OR EXISTS (
        SELECT 1
        FROM lms.module_versions
        JOIN lms.modules ON modules.id = module_versions.module_id
        WHERE module_versions.storage_path = storage.objects.name
          AND module_versions.is_current = TRUE
          AND modules.is_published = TRUE
          AND modules.deleted_at IS NULL
      )
    )
  );

CREATE POLICY "storage: study notes admin insert"
  ON storage.objects
  FOR INSERT
  WITH CHECK (
    bucket_id = 'study-notes'
    AND lms.is_admin()
    AND name LIKE 'modules/%'
  );

CREATE POLICY "storage: study notes admin update"
  ON storage.objects
  FOR UPDATE
  USING (bucket_id = 'study-notes' AND lms.is_admin())
  WITH CHECK (bucket_id = 'study-notes' AND lms.is_admin());

CREATE POLICY "storage: study notes admin delete"
  ON storage.objects
  FOR DELETE
  USING (bucket_id = 'study-notes' AND lms.is_admin());

